          "tips": "每天固定时间点练习问候语：起床时说Good morning，爸爸出门时说Bye-bye和Have a good day，睡前说Good night。重复是记忆的关键，不必急于让孩子掌握所有句子，先从最常用的Hello、Bye-bye、Good morning开始。",
          "description": "问候与告别是幼儿英语启蒙的第一步，也是日常使用频率最高的表达。通过简单的Hello和Bye-bye，孩子开始建立英语交流的信心。建议在每天起床、见到家人、出门和回家时反复练习。"
