          "tips": "起床和睡觉时的英语要温和、有节奏感。起床时用欢快的语调说\"Rise and shine\"，睡前用温柔的语调说\"Sleep tight\"。不要强迫孩子用英语回应，先让他们习惯听英语。可以建立固定的英语睡前仪式：换睡衣 → 刷牙 → 讲故事 → 盖被子 → 说晚安。仪式感会让孩子感到安全和舒适，也更容易接受英语。",
