          "tips": "如厕训练要用轻松、无压力的态度。如果孩子某天不愿意说英语，就先用中文，不要强迫。当孩子成功用英语表达如厕需求时，给予热情的表扬\"Good job!\" 意外发生时更要保持平和，说\"It's okay\"，避免孩子产生压力。记住，如厕训练的核心是生理 readiness，英语只是锦上添花。如果孩子还没准备好如厕训练，不要强求，先从词汇认知开始。",
          "description": "如厕训练是幼儿成长的重要里程碑，用英语进行如厕表达能帮助孩子更自然地表达需求。这些表达虽然私密，却是日常生活中不可或缺的实用口语。"
