          "tips": "零食时间是教孩子自我控制和健康意识的时机。当孩子要求更多零食时，坚定但温和地说\"That's enough\"或\"Wait until dinner\"。不要因为孩子哭闹就妥协，这会传递错误信息。同时，不要完全禁止零食，而是教他们适量和选择健康零食。用英语说\"Fruit is healthy\"、\"Candy is not healthy\" 让孩子建立健康概念。吃完零食记得提醒\"Brush your teeth after\" 建立口腔卫生意识。",
