          "tips": "礼貌教育最重要的是身教。孩子通过观察家长的行为学习，而不是通过说教。家长自己要先做到常说\"Please\"、\"Thank you\"、\"Excuse me\"。当孩子忘了说礼貌用语时，温和地提醒\"What do you say?\"而不是批评。表扬孩子的礼貌行为时要具体\"I like how you said please\"而不是笼统的\"Good job\"。记住，礼貌是发自内心的尊重，不是机械的套话。如果孩子只是机械地说\"Thank you\"而没有感情，不要强求，随着年龄增长他们会理解真正的含义。",
