          "tips": "情绪教育的核心是接纳。当孩子说\"I am angry\"时，不要说\"别生气\"，而是\"我知道你很生气\"，先接纳情绪再引导行为。每种情绪都是正常的，包括\"负面\"情绪，重要的是如何表达。教孩子用语言表达\"I am angry\"而不是推搡打人。当孩子情绪失控时，先帮助他们calm down，再讨论问题。家长也要表达自己的情绪\"I am frustrated\"给孩子做示范。记住，情绪智力比智商更能预测人生的成功和幸福，花时间培养是值得的。",
