          "tips": "职业认知教育要避免职业等级观念，强调每种工作都很重要。不要说\"你要好好学习，不然只能当清洁工\"，而要说\"清洁工让我们的城市干净，他们的工作很重要\"。当孩子说想当宇航员或总统时，不要嘲笑\"那太难了\"，而是说\"That would be amazing! What would you do as an astronaut?\"鼓励孩子做梦。带孩子接触真实的职场人士，比看书更有效。如果孩子对某个职业特别感兴趣，可以多提供相关材料：绘本、视频、玩具。记住，孩子的职业理想会随着年龄变化，今天想当医生明天想当恐龙，这完全正常。",
          "description": "职业认知帮助孩子了解社会分工，培养对不同职业的尊重。通过职业学习，孩子扩展词汇量，理解各种社会角色的功能和贡献。"
