          "tips": "看医生对很多孩子来说是恐惧的来源，提前准备很重要。在去之前，用玩偶演示会发生什么\"The doctor will look in your ears, look in your mouth, listen to your heart\"减少未知恐惧。永远不要骗孩子\"这不会疼\"如果实际上会疼，而是说\"这可能会有一点点疼，但很快就结束了，你非常勇敢\"。让孩子参与决策\"Do you want to sit on my lap or the chair?\"增加控制感。医疗体验会深刻影响孩子未来对医疗的态度，尽量让经历积极。如果孩子有特别的恐惧，提前和医生沟通，让他们知道如何温柔对待。记住，你的情绪会影响孩子，保持冷静和积极。",
