          "tips": "复习阶段要 celebration 而非 evaluation。重点不是孩子\"掌握了多少\"，而是他们\"愿意说多少\"。当孩子尝试用英语表达时，即使不完美也要热情回应。制作\"英语成就墙\"，贴出孩子学会的每个单词、每句话，让他们看到自己的进步。回顾最初的阶段，让孩子感受自己的成长\"Remember when you just learned 'hello'? Now you can say so much!\"复习不是重复，而是整合和应用。鼓励孩子创造性地组合所学内容，\"Make your own sentence\"比\"Repeat after me\"更有价值。最重要的是，让孩子感到学习英语是快乐的、值得的，他们为自己的进步骄傲。\r\n\r\n---",
